        .about {
            padding: 100px 50px;
            background: rgba(255, 255, 255, 0.9);
        }

        .about-content {
            max-width: 800px;
            margin: 0 auto;
        }

        .about img {
            width: 100%;
            border-radius: 5px;
            margin: 20px 0;
        }

        /* Projects Section */
        .projects {
            padding: 50px 20px;
            background: white;
        }

