                <h3>Project 3</h3>
                <p>Describe what this project does and its key features.</p>
            </div>
        </div>
    </section>

    <footer>
        <div class="footer">
            <p>Contact me at john.doe@example.com or visit my linkedin profile.</p>
            <img src="contact.jpg" alt="Contact">
        </div>
    </footer>
</body>
</html>
